-- Verified original FE questions from the IPA 2025/2026 public question booklets.
-- Official answer keys: 2025 A and 2026 A/B, compared question-by-question.
-- No visual-only or ambiguous diagrams were transcribed.
-- Insert with stable IDs; never delete or replace existing attempts/progress.
-- Source use: https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/index.html

INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES
('fe-ipa-official-2026-a-02','exam-fe','アルゴリズム','standard','single_choice','【2026年度 IPA公開問題 科目A 問2】クイックソートの処理方法を説明したものはどれか。','[{"id":"a","text":"既に整列済みのデータ列の正しい位置に，データを追加する操作を繰り返していく方法である。"},{"id":"b","text":"データ中の最小値を求め，次にそれを除いた部分の中から最小値を求める。この操作を繰り返していく方法である。"},{"id":"c","text":"適当な基準値を選び，それよりも小さな値のグループと大きな値のグループにデータを分割する。同様にして，グループの中で基準値を選び，それぞれのグループを分割する。この操作を繰り返していく方法である。"},{"id":"d","text":"隣り合ったデータの比較と入替えを繰り返すことによって，小さな値のデータを次第に端の方に移していく方法である。"}]','"c"','基準値（ピボット）で列を分割し，部分列を再帰的にソートする。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-03','exam-fe','コンピュータ構成','standard','single_choice','【2026年度 IPA公開問題 科目A 問3】プロセッサの一つである GPU の特徴として，適切なものはどれか。','[{"id":"a","text":"OS 及び他のハードウェアから独立して機能し，暗号キーなどの情報を安全に管理する。"},{"id":"b","text":"並列に動作する多数の浮動小数点演算ユニットによって，高速な 3D 演算ができる。"},{"id":"c","text":"目的に応じて半導体デバイス内部の論理回路を再構成できる。"},{"id":"d","text":"量子ビットによって 0 と 1 を重ね合わせた状態を計算に使うことができる。"}]','"b"','GPU は多数の演算ユニットによる並列処理に向く。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-04','exam-fe','クラウド','standard','single_choice','【2026年度 IPA公開問題 科目A 問4】クラウドコンピューティングのサービスモデルとしての PaaS の説明はどれか。','[{"id":"a","text":"OS やアプリケーションを含む任意のソフトウェアを実行可能にするリソースが，利用者に提供される。OS などのプラットフォームへの限定的な設定や制御を行うことができる。"},{"id":"b","text":"アプリケーションの開発や運用に必要となるミドルウェアなどが利用者に提供されるので，これらを利用して，アプリケーションを開発して運用することができる。利用者は，プラットフォームを直接変更することはできない。"},{"id":"c","text":"利用者は，ハードウェア，OS などのプラットフォームとアプリケーションを自ら準備して，それらの運用を依頼する。利用者は，プラットフォームの構成を決めることができるなど，環境構築の自由度が高い。"},{"id":"d","text":"利用者は，用意されたアプリケーションをそのまま又はカスタマイズして利用するが，OS などのプラットフォームからアプリケーションまで全てを自ら準備する必要はない。利用者は，プラットフォームを直接変更することはできない。"}]','"b"','PaaS はアプリ実行・開発基盤を提供し，利用者がその上にアプリを構築する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-05','exam-fe','システム構成','standard','single_choice','【2026年度 IPA公開問題 科目A 問5】仮想記憶方式のコンピュータシステムにおいて，処理の多重度を増やしたところ，ページイン，ページアウトが多発して，システムの応答速度が急激に遅くなった。このような現象を何というか。','[{"id":"a","text":"オーバレイ"},{"id":"b","text":"スラッシング"},{"id":"c","text":"メモリコンパクション"},{"id":"d","text":"ロールアウト"}]','"b"','ページ入出力が頻発し，CPU が実処理に使える時間が大幅に減る現象がスラッシング。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES
('fe-ipa-official-2026-a-08','exam-fe','ネットワーク','standard','single_choice','【2026年度 IPA公開問題 科目A 問8】無線 LAN では，複数の端末から送信された同じ周波数の電波が衝突した場合，電波が干渉するのでそれらを受信すると信号を復調できないことがある。この問題を回避するためのものはどれか。','[{"id":"a","text":"CSMA/CA"},{"id":"b","text":"SSID"},{"id":"c","text":"キャリアアグリゲーション"},{"id":"d","text":"テザリング"}]','"a"','CSMA/CA は衝突回避のため送信前のキャリア確認や待機を行う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-09','exam-fe','認証','standard','single_choice','【2026年度 IPA公開問題 科目A 問9】2 要素認証に該当する組みはどれか。','[{"id":"a","text":"クライアント証明書，ハードウェアトークン"},{"id":"b","text":"静脈認証，指紋認証"},{"id":"c","text":"パスワード認証，静脈認証"},{"id":"d","text":"パスワード認証，秘密の質問の答え"}]','"c"','パスワードは知識要素，静脈は生体要素である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-10','exam-fe','情報セキュリティ','standard','single_choice','【2026年度 IPA公開問題 科目A 問10】情報セキュリティに関する専門組織の説明のうち，CSIRT の説明として，最も適切なものはどれか。','[{"id":"a","text":"自社が顧客に提供する製品又はサービスの脆弱性に起因するリスクに対応する組織"},{"id":"b","text":"セキュリティインシデント検知のために，システム監視，ログ分析などのセキュリティ運用を担う組織"},{"id":"c","text":"発生したセキュリティインシデントに対し，インシデント対応を行う組織"},{"id":"d","text":"標的型サイバー攻撃特別相談窓口をもち，相談をもち込んだ組織の被害の低減と攻撃の連鎖の遮断を支援する組織"}]','"c"','CSIRT は実際のセキュリティインシデントへの対応・調整を担当する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-11','exam-fe','ソフトウェア開発','standard','single_choice','【2026年度 IPA公開問題 科目A 問11】あるシステムにおいて，“プログラムの記述方法が統一されていないので保守がしづらい”という問題が発生している。今後の新規開発プロジェクトにおけるこの問題の低減策として，最も適切なものはどれか。','[{"id":"a","text":"コーディング規約を見直し，教育する。"},{"id":"b","text":"セキュアプログラミングを採用する。"},{"id":"c","text":"単体テストでの命令網羅度を上げる。"},{"id":"d","text":"プロジェクト管理レビューに全プログラマーが参加する。"}]','"a"','ソースコード記述の統一にはコーディング規約の整備と教育が直接的に有効。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES
('fe-ipa-official-2026-a-12','exam-fe','プロジェクト管理','standard','single_choice','【2026年度 IPA公開問題 科目A 問12】バーンダウンチャートの使い方として，適切なものはどれか。','[{"id":"a","text":"縦軸を完成した成果物の総量，横軸を時間とし，プロジェクトが進むに従って完成した成果物の総量が増加する様子を確認する。"},{"id":"b","text":"縦軸を残課題の総数，横軸を時間とし，プロジェクトが進むに従って残課題の総量が増減する様子を確認する。"},{"id":"c","text":"縦軸を残作業の量，横軸を時間とし，プロジェクトが進むに従って残作業の量が減少する様子を確認する。"},{"id":"d","text":"縦軸を延べ工数，横軸を時間とし，プロジェクトが進むに従って延べ工数が増加する様子を確認する。"}]','"c"','バーンダウンチャートは横軸に時間，縦軸に残作業量をとり，残量が減る経過を示す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-13','exam-fe','プロジェクト管理','standard','single_choice','【2026年度 IPA公開問題 科目A 問13】あるシステム開発プロジェクトの進捗が遅延したので，クリティカルパス上の作業への投入工数を増やすことによって遅延の解消を図った。このとき適用した，所要期間を短縮するための手法を何と呼ぶか。','[{"id":"a","text":"クラッシング"},{"id":"b","text":"コーチング"},{"id":"c","text":"ファストトラッキング"},{"id":"d","text":"メンタリング"}]','"a"','資源投入で期間短縮するのがクラッシング。作業を並列化するのはファストトラッキング。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-14','exam-fe','可用性','standard','single_choice','【2026年度 IPA公開問題 科目A 問14】A 社は，自社のデータセンタでアプリケーションシステムを運用し，顧客にサービスを提供している。現在，アプリケーションシステムの実行環境をクラウドサービスに移行して，サービス可用性を向上させることを検討している。次の条件のとき，サービス可用性は移行後に何パーセントポイント向上するか。ここで，サービス可用性（％）は小数第 3 位を切り捨てるものとする。
〔条件〕
・サービス提供時間は，移行前も移行後も同じで，計画された保守の時間を除き，年間 5,000 時間である。
・移行前は，サービス提供時間内の停止時間が，年間 100 時間である。
・移行後は，サービス提供時間内の停止時間が，年間 30 分となる。','[{"id":"a","text":"0.01"},{"id":"b","text":"0.19"},{"id":"c","text":"1.40"},{"id":"d","text":"1.99"}]','"d"','移行前98.00%，移行後99.99%。差は1.99ポイント。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-a-16','exam-fe','マーケティング','standard','single_choice','【2026年度 IPA公開問題 科目A 問16】小売事業者が，オムニチャネル戦略を実現するための IT 活用事例はどれか。','[{"id":"a","text":"実店舗，オンライン店舗，コールセンタなど複数の顧客接点で，顧客情報や在庫情報などを一元的に管理・共有して接客することによって，顧客の利便性を高める。"},{"id":"b","text":"複数店舗からネットワークを経由して，受発注，出荷，請求，支払などの取引情報を電子的に交換することによって，卸売業者とメーカとの間の受発注業務の効率を高める。"},{"id":"c","text":"複数店舗に設置した監視カメラの画像データを本部に集め，本部が各店舗の状況をリアルタイムに把握することによって，店舗運営業務の効率を高める。"},{"id":"d","text":"複数店舗の POS データを本部に集め，本部が日次で売れ筋商品の抽出，複数の商品の併売率の分析を行うことによって，商品計画や棚割計画を最適化する。"}]','"a"','顧客接点を横断して顧客情報・在庫情報を一元管理し，同じ顧客体験を提供する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES
('fe-ipa-official-2026-a-19','exam-fe','組織・発想法','standard','single_choice','【2026年度 IPA公開問題 科目A 問19】ブレーンストーミングの説明はどれか。','[{"id":"a","text":"あるテーマの検討において，複数のメンバーで，各自が思いつくままに自由奔放にできるだけ多くのアイディアを出し合うことによって，創造的思考を喚起し，アイディアを開発しようとする会議方法"},{"id":"b","text":"研修を始める前に行う簡単なゲームや，商談や面接の本題に入る前に行う雑談など，参加者の緊張をほぐすためのコミュニケーション方法"},{"id":"c","text":"情報を，決められた枠組みに従って整理・分析するスキルや方法を利用し，複雑なものごとを明快に把握したり，問題に対する解決策を導き出したりするような思考方法"},{"id":"d","text":"ポイントを繰り返したり，言い換えたりすることによって，お互いの理解する意味合いが一致していることを確認したり，意見・評価を伝えたりする方法"}]','"a"','自由な発想を多数出し合う集団発想法である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2026-b-01','exam-fe','FE算法与程序设计','standard','single_choice','【2026年度 IPA公開問題 科目B 問1】次のプログラム中の空欄に入れる正しい答えを，解答群の中から選べ。ここで，配列の要素番号は 1 から始まる。

次のプログラムは，整数型の配列 data の末尾の要素の値を先頭の要素に移動する。この際，末尾以外の各要素の値は，一つずつ後ろの要素に移動する。

〔プログラム〕
整数型の配列: data ← {1, 2, 3, 4, 5, 6, 7, 8, 9}
整数型: top, i
整数型: len ← data の要素数
top ← data[len]
for (i を［　］)
  data[i] ← data[i − 1]
endfor
data[1] ← top','[{"id":"a","text":"2 から len − 1 まで 1 ずつ増やす"},{"id":"b","text":"2 から len まで 1 ずつ増やす"},{"id":"c","text":"len − 1 から 2 まで 1 ずつ減らす"},{"id":"d","text":"len から 2 まで 1 ずつ減らす"}]','"d"','元の配列の値を上書きしないよう末尾から先頭へ順番に一つずつ移動する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_fe_kamoku_b_qs.pdf','ja','B','explicit'),
('fe-ipa-official-2025-a-01','exam-fe','AI・機械学習','standard','single_choice','【2025年度 IPA公開問題 科目A 問1】大規模言語モデルを用いた自然言語処理において，事前学習済みのモデルに対して行う，ファインチューニングに関する記述として，最も適切なものはどれか。','[{"id":"a","text":"強化学習を行い，最適な結果が得られるようにする。"},{"id":"b","text":"事前学習と同じデータを繰り返し用いて学習を行い，モデルの精度を高めるようにする。"},{"id":"c","text":"大量のテキストデータを用いて学習を行い，モデルの精度を高めるようにする。"},{"id":"d","text":"特定のデータを用いて追加で学習を行い，目的とするタスクに適用できるようにする。"}]','"d"','ファインチューニングは特定の用途に応じた追加学習。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2025-a-02','exam-fe','数値計算','standard','single_choice','【2025年度 IPA公開問題 科目A 問2】浮動小数点形式で表現された数値の演算結果における丸め誤差の説明はどれか。','[{"id":"a","text":"演算結果がコンピュータの扱える最大値を超えることによって生じる誤差である。"},{"id":"b","text":"数表現のけた数に限度があるので，最下位けたより小さい部分について四捨五入や切上げ，切捨てを行うことによって生じる誤差である。"},{"id":"c","text":"乗除算において，指数部が小さい方の数値の仮数部の下位部分が失われることによって生じる誤差である。"},{"id":"d","text":"絶対値がほぼ等しい数値の加減算において，上位の有効数字が失われることによって生じる誤差である。"}]','"b"','表現できる桁数の制約から桁を丸める際に生じる誤差。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf','ja','A','explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES
('fe-ipa-official-2025-a-05','exam-fe','ソフトウェア開発','standard','single_choice','【2025年度 IPA公開問題 科目A 問5】ローコード開発ツールを用いたソフトウェア開発の説明はどれか。','[{"id":"a","text":"アプリケーションソフトウェアの開発基盤の上で，用意された部品やテンプレートを GUI を用いた操作で組み合わせたり，必要に応じて一部の処理のソースコードを記述したりすることによって，アプリケーションソフトウェアを作成する。"},{"id":"b","text":"アプリケーションソフトウェアの開発基盤の上で，用意された部品やテンプレートを GUI を用いた操作で組み合わせるだけで，ソースコードを記述せずに，アプリケーションソフトウェアを作成する。"},{"id":"c","text":"アプリケーションソフトウェアの定型的な枠組みを参照して，独自の処理のソースコードを記述することによって，アプリケーションソフトウェアを作成する。"},{"id":"d","text":"利用者がシステムを利用して行う作業を自動化ツールに代行させるために，利用者によるシステムの操作手順をツールに登録する。"}]','"a"','ローコードはGUI部品と必要最低限のコードを組み合わせて開発する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2025-a-08','exam-fe','ネットワーク','standard','single_choice','【2025年度 IPA公開問題 科目A 問8】HTTP と HTTPS を比較した場合において，HTTPS だけがもつ特徴を示したものはどれか。','[{"id":"a","text":"cookie に保存されている情報を用いたセッション管理が可能である。"},{"id":"b","text":"ID とパスワードによって利用者の認証を行うことが可能である。"},{"id":"c","text":"Web ブラウザでキャッシュさせることによって通信量を減らすことが可能である。"},{"id":"d","text":"通信相手先サーバをサーバ証明書によって確認することが可能である。"}]','"d"','HTTPS はTLSによってサーバ証明書を検証する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2025-a-10','exam-fe','情報セキュリティ','standard','single_choice','【2025年度 IPA公開問題 科目A 問10】WAF の説明はどれか。','[{"id":"a","text":"Web サイトに対するアクセス内容を監視し，攻撃とみなされるパターンを検知したときに当該アクセスを遮断する。"},{"id":"b","text":"Wi-Fi アライアンスが認定した無線 LAN の暗号化方式の規格であり，AES 暗号に対応している。"},{"id":"c","text":"様々なシステムの動作ログを一元的に蓄積，管理し，セキュリティ上の脅威となる事象をいち早く検知，分析する。"},{"id":"d","text":"ファイアウォール機能を有し，マルウェア対策機能，侵入検知機能などの複数のセキュリティ機能を連携させ，統合的に管理する。"}]','"a"','WAFはHTTPリクエストを検査しWebアプリへの攻撃を遮断する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2025-a-11','exam-fe','データベース','standard','single_choice','【2025年度 IPA公開問題 科目A 問11】E-R モデルにおけるエンティティの特徴はどれか。','[{"id":"a","text":"エンティティとインスタンスとは，1 対 1 の対応関係をとる。"},{"id":"b","text":"エンティティとなり得るものは，物的に実現するものである。"},{"id":"c","text":"エンティティは，特性を表すための属性（アトリビュート）をもつ。"},{"id":"d","text":"異なった種類のエンティティ間の関係は，主として状態遷移として表現される。"}]','"c"','エンティティは属性を持ち，物理的な物体以外の概念も表現できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf','ja','A','explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES
('fe-ipa-official-2025-a-12','exam-fe','プログラミング','standard','single_choice','【2025年度 IPA公開問題 科目A 問12】オブジェクト指向プログラミングの特徴のうち，異なるクラスのオブジェクトを同一のインタフェースで操作したときに，操作対象クラスに応じた異なる動作を可能にすることを何と呼ぶか。','[{"id":"a","text":"委譲"},{"id":"b","text":"継承"},{"id":"c","text":"コンポジション"},{"id":"d","text":"多相性"}]','"d"','同一インタフェースでもオブジェクトの型に応じて動作が変わる多相性。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf','ja','A','explicit'),
('fe-ipa-official-2025-a-13','exam-fe','アジャイル開発','standard','single_choice','【2025年度 IPA公開問題 科目A 問13】アジャイル開発手法の一つであるスクラムにおいて，プロダクトバックログアイテムの内容や並び順を決定する役割をもつのは誰か。','[{"id":"a","text":"開発者"},{"id":"b","text":"顧客"},{"id":"c","text":"スクラムマスタ"},{"id":"d","text":"プロダクトオーナ"}]','"d"','プロダクトオーナはバックログの内容や順番に責任を持つ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf','ja','A','explicit');
